export function makeBaseValues() {
  const historical_frame={version:1,schema:'historical_frame',request_id:requestId,region:{region_id:'region-1'},year:{value:1230},calendar:{season:'winter'},clock:structuredClone(clock)};
  const g5_scene_graph={version:1,schema:'g5_scene_graph_draft',request_id:requestId,parent_location:{region_id:'region-1',place_id:'place-1',location_id:'g4-1',g4_node_id:'g4-1'},player_start_position:{region_id:'region-1',place_id:'place-1',location_id:'g4-1',g4_node_id:'g4-1',minilocation_id:'mini-1',anchor_id:'anchor-1'},g5_minilocations:[{g5_minilocation_id:'mini-1'}],g5_anchors:[{anchor_id:'anchor-1',parent_minilocation_id:'mini-1'}],g5_edges:[],visibility_model:{visible_anchor_ids:['anchor-1'],hidden_anchor_ids:[],requires_inspection_anchor_ids:[],light_profile:'twilight'}};
  return {request_id:requestId,historical_frame,weather_state:structuredClone(weatherState),selected_start_node:{version:1,schema:'selected_start_node',request_id:requestId,selected_node_chain:{g4_node_id:'g4-1'}},player_character:{version:1,schema:'player_character_game_profile',request_id:requestId,player_character_id:'pc-1',character_id:'pc-1',body:{}},g5_scene_graph,g5_scene_audit:{version:1,schema:'g5_scene_audit',request_id:requestId,pass:true},initial_npc_placement:{version:1,schema:'initial_npc_placement_draft',request_id:requestId,placement_status:'empty_allowed',npc_instances:[]},npc_placement_audit:{version:1,schema:'initial_npc_placement_audit',request_id:requestId,pass:true},initial_item_placement:{version:1,schema:'initial_item_placement_draft',request_id:requestId,placement_status:'empty_allowed',item_instances:[],container_instances:[]},item_placement_audit:{version:1,schema:'initial_item_placement_audit',request_id:requestId,pass:true}};
}
export function makeStage17Input(mutator=null){const values=makeBaseValues();mutator?.(values);return stage17.buildStage17TimeLightInput(values);}
