export function makeStage18Input(mutator=null){const base=makeBaseValues();const timeAudit=makeStage17Audit(stage17.buildStage17TimeLightInput(base));const values={...base,start_place_audit:{version:1,schema:'start_place_audit',request_id:requestId,pass:true},player_character_audit:{version:1,schema:'player_character_audit',request_id:requestId,pass:true},current_position:{region_id:'region-1',place_id:'place-1',location_id:'g4-1',minilocation_id:'mini-1',anchor_id:'anchor-1',last_route_id:null},time_light_consistency_audit:timeAudit,regional_context_package:{version:1,schema:'regional_context_package',request_id:requestId,source_id:'region-source'},world_base_route_snapshot:{version:1,schema:'world_base_route_snapshot',nearby_graph_edges:[],known_route_candidates:[],historical_anchor_candidates:[],route_knowledge_rule_candidates:[]}};mutator?.(values);return stage18.buildStage18CharacterKnowledgeInput(values);}
export function makeKnowledgeMap(input=makeStage18Input(),overrides={}){return{version:1,schema:stage18.STAGE18_OUTPUT_SCHEMA,request_id:requestId,knowledge_status:'empty_limited',character_ref:{player_character_id:'pc-1'},current_position_ref:{region_id:'region-1',g4_node_id:'g4-1',minilocation_id:'mini-1',anchor_id:'anchor-1'},knowledge_scope_summary:{map_detail_level:'local',route_knowledge_level:'none'},player_vs_character_knowledge_boundary:{ui_guidance:{}},downstream_constraints:{},audit_self_check:{pass:true,concerns:[],evidence:[{kind:'self'}]},known_routes:[],known_nearby_paths:[],known_places:[],known_addresses:[],known_landmarks:[],known_people:[],known_authorities:[],known_dangers:[],known_social_rules:[],known_resources:[],rumors:[],mistaken_beliefs:[],uncertain_knowledge:[],forbidden_knowledge:[],knowledge_gaps:[],source_trace:[{source_id:'region-source'}],...overrides};}
