export function makeStage19Input(mutator=null){const base=makeBaseValues();const i18=makeStage18Input();const map=makeKnowledgeMap(i18);const a18={...makeStage18Audit(),commit_permission:{can_commit_character_knowledge:true,can_continue_to_hidden_state:true}};const values={...base,time_light_consistency_audit:i18.time_light_consistency_audit,character_knowledge_map:map,character_knowledge_map_audit:a18,regional_context_package:i18.regional_context_package,world_base_route_snapshot:i18.world_base_route_snapshot};mutator?.(values);return stage19.buildStage19HiddenStateInput(values);}
export function makeHiddenState(input=makeStage19Input(),overrides={}){const output={version:1,schema:stage19.STAGE19_OUTPUT_SCHEMA,request_id:requestId,hidden_state_status:'empty_limited',frame:{region_id:'region-1',year:1230,season:'winter',clock:structuredClone(clock),weather_state:structuredClone(weatherState)},parent_scene:{g4_node_id:'g4-1',player_current_anchor_id:'anchor-1'},player_facing_boundary:{},source_trace:[{source_id:'region-source'}],audit_self_check:{pass:true,concerns:[],evidence:[{kind:'self'}]}};for(const key of ['hidden_npc_state','hidden_access_state','hidden_property_state','hidden_container_state','hidden_item_state','hidden_risk_state','hidden_event_state','hidden_social_state','hidden_route_state','hidden_environment_state','discovery_rules','reveal_conditions','consequence_hooks','forbidden_output_rules'])output[key]=[];return Object.assign(output,overrides);}
